export interface InstrumentPreset {
  id: string;
  name: string;
  czName: string;
  category: string;
  czCategory: string;
  icon: string;
  description: string;
  soundfont: string; // Real General MIDI SoundFont multi-sample instrument name
  synthType: 'piano' | 'rhodes' | 'fm_ep' | 'organ' | 'clavinet' | 'strings_arco' | 'strings_pizz' | 'brass' | 'woodwind' | 'flute' | 'guitar_acoustic' | 'guitar_electric' | 'guitar_nylon' | 'bass_electric' | 'bass_synth' | 'bass_upright' | 'synth_lead' | 'synth_pad' | 'world_plucked' | 'mallet' | 'percussion';
  octaveShift?: number;
  decay?: number;
  release?: number;
  brightness?: number; // Filter cutoff multiplier
  resonance?: number;
  vibrato?: number;
  harmonicCount?: number;
  subOsc?: boolean;
}

export interface InstrumentCategory {
  id: string;
  name: string;
  czName: string;
  icon: string;
  instruments: InstrumentPreset[];
}

